INSERT INTO alarm_defs (tag_id, kind, limit_value, hysteresis, delay_ms, priority, message)
SELECT t.id, a.kind, a.lim, a.hyst, a.delay, a.prio, a.msg FROM (VALUES
 ('KNS1_Level',    'hihi', 3.5,  0.05, 0,    1, 'Аварийно высокий уровень в резервуаре'),
 ('KNS1_Level',    'hi',   3.0,  0.05, 2000, 2, 'Высокий уровень в резервуаре'),
 ('KNS1_Level',    'lo',   0.9,  0.05, 2000, 3, 'Низкий уровень — защита от сухого хода'),
 ('KNS1_Pressure', 'hi',   3.45, 0.05, 3000, 3, 'Повышенное давление в коллекторе'),
 ('KNS1_P1_Temp',  'hi',   70,   1,    5000, 2, 'Перегрев обмотки двигателя Н-1'),
 ('KNS1_P1_Fault', 'discrete_on', NULL, 0, 0, 1, 'Авария насоса Н-1'),
 ('KNS1_Door',     'discrete_on', NULL, 0, 0, 4, 'Открыта дверь КНС'),
 ('KNS2_Level',    'bad_quality', NULL, 0, 5000, 2, 'Нет связи с ПЛК КНС-2')
) AS a(tag, kind, lim, hyst, delay, prio, msg)
JOIN tags t ON t.name = a.tag;

